import { useState, type ReactNode } from "react";
import { useModalDialog } from "./PrecisionOperationsPreviewPage";
import { AutomationIcon, InstagramMarkIcon, SearchIcon, PlusIcon, ChevronDownIcon, CheckCircleIcon, InboxIcon, DotsVerticalIcon, SendIcon, SunIcon, MoonIcon } from "../components/icons";
import { Logo } from "../components/Logo";

export type FullPreviewScreen = "overview" | "automations" | "builder" | "inbox" | "leads" | "lead-detail" | "knowledge" | "content" | "analytics" | "integrations" | "team" | "billing" | "settings" | "login" | "connect-error" | "invite";
export type PreviewPalette = "navy-cobalt" | "teal-emerald" | "slate-cyan" | "forest-slate" | "orange-amber" | "neutral-slate" | "ocean-blue" | "rose-graphite" | "amber-minimal" | "ocean-sky" | "jade-mint" | "rose-slate" | "amber-graphite";
type Go = (screen: FullPreviewScreen) => void;
function Tag({ children, tone = "neutral" }: { children: ReactNode; tone?: string }) { return <span className={"po-tag po-tag--" + tone}>{children}</span>; }
function Panel({ children, className = "" }: { children: ReactNode; className?: string }) { return <section className={"po-content-panel " + className}>{children}</section>; }
function PanelTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <header className="po-panel-title"><div>{eyebrow && <span className="po-eyebrow">{eyebrow}</span>}<h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</header>;
}
function Metric({ label, value, note }: { label: string; value: string; note: string }) { return <div className="po-metric"><span>{label}</span><strong>{value}</strong><small>{note}</small></div>; }
const sampleConversations = [
  { handle:"@sample_fitness", preview:"Do you have pricing for 1:1 coaching?", time:"2m", status:"AI handling", tone:"purple", initial:"SF" },
  { handle:"@studio_owner", preview:"Can you share the class schedule?", time:"12m", status:"Needs review", tone:"amber", initial:"SO" },
  { handle:"@maya_runs", preview:"Is this available for beginners?", time:"27m", status:"AI handling", tone:"purple", initial:"MR" },
];

export function OverviewScreen({ onNavigate }: { onNavigate: Go }) {
  const [period, setPeriod] = useState("Last 7 days");
  const [definitions, setDefinitions] = useState(false);
  return <section>
    <div className="po-screen-toolbar"><span className="po-sample-label">SAMPLE WORKSPACE DATA · NOT LIVE METRICS</span><label className="po-select-wrap"><span className="po-visually-hidden">Reporting period</span><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Last 7 days</option><option>Last 30 days</option><option>This month</option><option>All time</option></select><ChevronDownIcon/></label></div>
    <div className="po-metric-row po-overview-metrics"><Metric label="New leads" value="19" note={"in " + period.toLowerCase()}/><Metric label="Qualified leads" value="2" note="current sample pipeline"/><Metric label="Meetings scheduled" value="0" note="no meeting records in sample"/><Metric label="Revenue" value="—" note="Revenue tracking not configured"/></div>
    <div className="po-overview-grid">
      <Panel><PanelTitle eyebrow="CONVERSATION VOLUME" title="Activity over time" description="Count of inbound comments and DMs. Not a conversion rate." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("analytics")}>Open analytics →</button>}/><div className="po-chart-summary"><strong>164</strong><span>inbound events · illustrative period: {period}</span></div><div className="po-minibars" role="img" aria-label="Illustrative daily conversation volume">{[18,26,21,34,25,32,8].map((n,i)=><div className="po-minibar-col" key={i}><b className="po-minibar-value">{n}</b><div className="po-minibar-track"><span style={{height:Math.max(5,n/34*100)+"%"}}/></div><small>{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][i]}</small></div>)}</div></Panel>
      <Panel><PanelTitle eyebrow="LEAD PIPELINE" title="24 leads by stage" description="Unique lead records; totals reconcile." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("leads")}>View leads →</button>}/><div className="po-stage-list">{[["New",19],["Contacted",3],["Qualified",2]].map(([name,n])=><div className="po-stage-row" key={name as string}><span>{name}</span><div className="po-stage-track"><span style={{width:Number(n)/24*100+"%"}}/></div><strong>{n}</strong><Tag>{Math.round(Number(n)/24*100)}%</Tag></div>)}</div><div className="po-note-line"><CheckCircleIcon/><span>19 + 3 + 2 = 24 leads; no unclassified sample leads.</span></div></Panel>
      <Panel><PanelTitle eyebrow="NEXT ACTIONS" title="Needs your attention" description="Tasks that need an operator." action={<Tag tone="warning">4 items</Tag>}/>{[["Review conversations","2 conversations need a human review","inbox"],["Assign lead owners","2 leads are unassigned","leads"],["Finish an automation draft","Lead qualification is not live","builder"],["Check account health","Review permissions and last event","integrations"]].map((item,i)=><button type="button" className="po-action-row" key={item[0]} onClick={()=>onNavigate(item[2] as FullPreviewScreen)}><span className="po-action-number">0{i+1}</span><span><strong>{item[0]}</strong><small>{item[1]}</small></span><span className="po-action-arrow">→</span></button>)}</Panel>
      <Panel><PanelTitle eyebrow="RECENT CONVERSATIONS" title="Latest activity" description="Recent sample inbound messages." action={<button type="button" className="po-text-action" onClick={()=>onNavigate("inbox")}>Open inbox →</button>}/><div className="po-recent-list">{sampleConversations.map(item=><button type="button" className="po-recent-item" key={item.handle} onClick={()=>onNavigate("inbox")}><span className="po-avatar">{item.initial}</span><span><strong>{item.handle}</strong><small>{item.preview}</small></span><Tag tone={item.tone}>{item.status}</Tag><small>{item.time}</small></button>)}</div></Panel>
    </div>
    <button type="button" className="po-help-text" onClick={()=>setDefinitions(v=>!v)}>{definitions?"Hide metric definitions ↑":"How are these metrics counted? ↓"}</button>{definitions&&<div className="po-definition-block"><strong>Metric definitions</strong><p>Lead metrics count unique lead records. Conversation volume counts events, so one person may send multiple messages. Activity is not a lead conversion rate.</p></div>}
  </section>;
}

const automationRows = [
  {id:"1",name:"Lead qualification",summary:"Ask what the person needs, then capture the answer",trigger:"Comment or DM keywords",account:"@creatorstudio",status:"Draft",updated:"Today"},
  {id:"2",name:"Pricing enquiries",summary:"Answer common price questions from business knowledge",trigger:"DM keyword",account:"@creatorstudio",status:"Live",updated:"Yesterday"},
  {id:"3",name:"New post comments",summary:"Start a conversation when someone comments on a post",trigger:"Comment",account:"@creatorstudio",status:"Live",updated:"Oct 10"},
  {id:"4",name:"Class schedule help",summary:"Share a schedule and offer human follow-up",trigger:"DM keyword",account:"@studioaccount",status:"Paused",updated:"Oct 08"},
  {id:"5",name:"Product interest capture",summary:"Collect the product category a person is interested in",trigger:"Comment",account:"Account not assigned",status:"Needs publishing",updated:"Oct 06"},
  {id:"6",name:"Opening hours",summary:"Share opening hours and answer location questions",trigger:"DM keyword",account:"@creatorstudio",status:"Live",updated:"Oct 05"},
  {id:"7",name:"New follower questions",summary:"Offer the next step when a new follower asks for details",trigger:"DM keyword",account:"@creatorstudio",status:"Paused",updated:"Oct 03"},
  {id:"8",name:"Event enquiries",summary:"Collect interest in an upcoming event",trigger:"Comment",account:"@studioaccount",status:"Draft",updated:"Oct 02"},
  {id:"9",name:"Book a consultation",summary:"Ask for a preferred consultation time",trigger:"DM keyword",account:"@creatorstudio",status:"Live",updated:"Sep 30"},
  {id:"10",name:"Return policy questions",summary:"Handle common policy questions and route edge cases",trigger:"DM keyword",account:"@creatorstudio",status:"Live",updated:"Sep 28"},
  {id:"11",name:"Human review requests",summary:"Route explicit requests for a person to a follow-up queue",trigger:"Comment or DM keywords",account:"@studioaccount",status:"Draft",updated:"Sep 26"},
];
const templates = [
  {name:"Qualify new leads",outcome:"Ask one or two questions and capture the answer on the lead.",trigger:"Comment or DM",flow:"Trigger → AI reply → Goal",note:"Best starting point"},
  {name:"Answer common questions",outcome:"Use approved business knowledge to answer enquiries.",trigger:"Direct message",flow:"Trigger → Knowledge-backed reply",note:"Requires ready knowledge"},
  {name:"Route complex questions",outcome:"Spot uncertain questions and guide a person into the conversation.",trigger:"Direct message",flow:"Trigger → Reply guidance",note:"Review escalation rules"},
];
type BuilderSeed = { triggerType: string; keywords: string };

export function AutomationsScreen({onOpenBuilder}:{onOpenBuilder:(name:string,status?:string,newDraft?:boolean,seed?:BuilderSeed)=>void}) {
  const [items,setItems] = useState(automationRows);
  const [tab,setTab] = useState("mine");
  const [showCreate,setShowCreate] = useState(false);
  const [draftName,setDraftName] = useState("");
  const [draftKeywords,setDraftKeywords] = useState("price, quote, details");
  const [draftTrigger,setDraftTrigger] = useState("both");
  const [query,setQuery] = useState("");
  const [status,setStatus] = useState("All statuses");
  const [trigger,setTrigger] = useState("All start conditions");
  const [sort,setSort] = useState("Recently updated");
  const [notice,setNotice] = useState("");
  const [page,setPage] = useState(1);
  const [selectedIds,setSelectedIds] = useState<Set<string>>(new Set());
  const [openActionId,setOpenActionId] = useState<string|null>(null);
  const [renameItem,setRenameItem] = useState<(typeof automationRows)[number]|null>(null);
  const [renameValue,setRenameValue] = useState("");
  const [deleteItem,setDeleteItem] = useState<(typeof automationRows)[number]|null>(null);
  const [bulkAction,setBulkAction] = useState<"activate"|"pause"|null>(null);
  const [confirmSingleActivation,setConfirmSingleActivation] = useState<(typeof automationRows)[number]|null>(null);
  const createRef = useModalDialog(showCreate, () => setShowCreate(false));
  const renameRef = useModalDialog(Boolean(renameItem), () => setRenameItem(null));
  const deleteRef = useModalDialog(Boolean(deleteItem), () => setDeleteItem(null));
  const bulkRef = useModalDialog(Boolean(bulkAction), () => setBulkAction(null));
  const activateRef = useModalDialog(Boolean(confirmSingleActivation), () => setConfirmSingleActivation(null));

  const filtered = items.filter(r =>
    (!query || (r.name+" "+r.summary+" "+r.account).toLowerCase().includes(query.toLowerCase().trim())) &&
    (status==="All statuses" || r.status===status) &&
    (trigger==="All start conditions" || r.trigger===trigger)
  );
  const rows=[...filtered].sort((a,b)=>{
    if(sort==="Name A–Z") return a.name.localeCompare(b.name);
    if(sort==="Name Z–A") return b.name.localeCompare(a.name);
    if(sort==="Status") return a.status.localeCompare(b.status);
    if(sort==="Oldest updated") return items.findIndex(x=>x.id===b.id)-items.findIndex(x=>x.id===a.id);
    if(a.updated==="Just now"&&b.updated!=="Just now") return -1;
    if(b.updated==="Just now"&&a.updated!=="Just now") return 1;
    return items.findIndex(x=>x.id===a.id)-items.findIndex(x=>x.id===b.id);
  });
  const pageSize=10;
  const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));
  const visibleRows=rows.slice((page-1)*pageSize,page*pageSize);
  const allVisibleSelected=visibleRows.length>0&&visibleRows.every(r=>selectedIds.has(r.id));
  const selectedRows=items.filter(r=>selectedIds.has(r.id));
  const eligibleToActivate=selectedRows.filter(r=>r.status==="Paused");
  const eligibleToPause=selectedRows.filter(r=>r.status==="Live");

  function updateLocalStatus(ids:string[],nextStatus:string) {
    setItems(current=>current.map(item=>ids.includes(item.id)?{...item,status:nextStatus,updated:"Just now"}:item));
    setSelectedIds(new Set());
    setPage(1);
    setBulkAction(null);
    setOpenActionId(null);
    setNotice("Sample status updated to “"+nextStatus+"”. No production automation was changed.");
  }
  function resetFilters() {
    setQuery("");setStatus("All statuses");setTrigger("All start conditions");setSort("Recently updated");setPage(1);
  }
  function openRow(row:(typeof automationRows)[number]) {
    const source=row.trigger==="Comment"?"comment":row.trigger==="DM keyword"?"message":"both";
    const keywords=row.name.toLowerCase().includes("pricing")?"price, pricing, cost":row.name.toLowerCase().includes("schedule")?"schedule, class, timings":"price, quote, details";
    onOpenBuilder(row.name,row.status,false,{triggerType:source,keywords});
  }
  function createFromTemplate(t:(typeof templates)[number]) {
    const source=t.trigger.toLowerCase().includes("comment")&&t.trigger.toLowerCase().includes("dm")?"both":t.trigger.toLowerCase().includes("comment")?"comment":"message";
    onOpenBuilder(t.name,"Draft",true,{triggerType:source,keywords:t.trigger.toLowerCase().includes("comment")?"price, details":"price, quote, details"});
  }

  return <section className="po-automations-page">
    <div className="po-tab-bar" role="tablist" aria-label="Automation sections">
      <button type="button" role="tab" id="po-automation-tab-mine" aria-selected={tab==="mine"} aria-controls="po-automation-panel" className={tab==="mine"?"is-active":""} onClick={()=>setTab("mine")}>My automations</button>
      <button type="button" role="tab" id="po-automation-tab-templates" aria-selected={tab==="templates"} aria-controls="po-automation-panel" className={tab==="templates"?"is-active":""} onClick={()=>setTab("templates")}>Start from a template</button>
    </div>
    <div id="po-automation-panel" role="tabpanel" aria-labelledby={tab==="mine"?"po-automation-tab-mine":"po-automation-tab-templates"}>
      <div className="po-outcome-banner"><span className="po-outcome-marker"><AutomationIcon/></span><div><strong>Start with the outcome you want</strong><p>Pick a ready-made automation and customize only the parts that matter. Your changes stay in draft until you explicitly publish.</p></div><button type="button" className="po-button po-button--primary" onClick={()=>setTab("templates")}>Choose a template</button></div>
      {tab==="mine"?<>
        <div className="po-list-toolbar"><div><h2>My automations ({items.length})</h2><p>Choose a journey to edit its trigger, reply behavior, and lead capture.</p></div><button type="button" className="po-button po-button--primary" onClick={()=>{setDraftName("");setDraftKeywords("price, quote, details");setDraftTrigger("both");setShowCreate(true);}}>Create draft</button></div>
        <div className="po-automation-filters">
          <div className="po-automation-search"><label htmlFor="po-automation-search">Search</label><div className="po-search"><SearchIcon/><input id="po-automation-search" type="search" value={query} onChange={e=>{setQuery(e.target.value);setPage(1);setSelectedIds(new Set());}} placeholder="Search automations…"/>{query&&<button type="button" aria-label="Clear search" onClick={()=>{setQuery("");setPage(1);}}>×</button>}</div></div>
          <label className="po-automation-filter">Status<select value={status} onChange={e=>{setStatus(e.target.value);setPage(1);setSelectedIds(new Set());}}><option>All statuses</option><option>Live</option><option>Paused</option><option>Draft</option><option>Needs publishing</option></select></label>
          <label className="po-automation-filter">Start condition<select value={trigger} onChange={e=>{setTrigger(e.target.value);setPage(1);setSelectedIds(new Set());}}><option>All start conditions</option><option>Comment</option><option>DM keyword</option><option>Comment or DM keywords</option></select></label>
          <label className="po-automation-filter">Sort by<select value={sort} onChange={e=>{setSort(e.target.value);setPage(1);}}><option>Recently updated</option><option>Oldest updated</option><option>Name A–Z</option><option>Name Z–A</option><option>Status</option></select></label>
        </div>
        {notice&&<div className="po-inline-notice" role="status"><span>{notice}</span><button type="button" aria-label="Dismiss status notice" onClick={()=>setNotice("")}>×</button></div>}
        {selectedIds.size>0&&<div className="po-bulk-toolbar"><strong>{selectedIds.size} selected</strong><div><button type="button" disabled={!eligibleToActivate.length} onClick={()=>setBulkAction("activate")}>Activate {eligibleToActivate.length>0?"("+eligibleToActivate.length+")":""}</button><button type="button" disabled={!eligibleToPause.length} onClick={()=>setBulkAction("pause")}>Pause {eligibleToPause.length>0?"("+eligibleToPause.length+")":""}</button><button type="button" className="po-bulk-clear" onClick={()=>setSelectedIds(new Set())}>Clear</button></div></div>}
        <div className="po-automation-table-wrap">
          {rows.length===0?<div className="po-table-empty"><strong>{query||status!=="All statuses"||trigger!=="All start conditions"?"No automations match your filters":"No automations yet"}</strong><span>Try changing the search or filter, or create a draft to start a new journey.</span><button type="button" className="po-text-action" onClick={resetFilters}>Clear filters</button></div>:<><div className="po-automation-mobile-list">{visibleRows.map(r=><article className="po-automation-mobile-card" key={r.id}><div className="po-automation-mobile-card-top"><input type="checkbox" aria-label={"Select "+r.name} checked={selectedIds.has(r.id)} onChange={()=>setSelectedIds(current=>{const next=new Set(current);if(next.has(r.id))next.delete(r.id);else next.add(r.id);return next;})}/><div className="po-automation-mobile-card-title"><button type="button" className="po-table-primary-link" onClick={()=>openRow(r)}>{r.name}</button><small>{r.summary||r.trigger+" · sample keywords"}</small></div><div className="po-action-menu-wrap"><button type="button" className="po-icon-button" aria-label={"Actions for "+r.name} aria-expanded={openActionId===r.id} onClick={()=>setOpenActionId(current=>current===r.id?null:r.id)}><DotsVerticalIcon/></button>{openActionId===r.id&&<><button className="po-action-dismiss" type="button" aria-label="Close action menu" onClick={()=>setOpenActionId(null)}/><div className="po-action-menu" role="group" aria-label={"Actions for "+r.name}><button type="button" onClick={()=>{setOpenActionId(null);openRow(r);}}>Open</button><button type="button" onClick={()=>{setOpenActionId(null);setRenameItem(r);setRenameValue(r.name);}}>Rename</button>{r.status==="Draft"&&<button type="button" className="is-danger" onClick={()=>{setOpenActionId(null);setDeleteItem(r);}}>Delete draft</button>}<button type="button" disabled={r.status==="Draft"||r.status==="Needs publishing"} onClick={()=>{if(r.status==="Paused"){setOpenActionId(null);setConfirmSingleActivation(r);}else if(r.status==="Live"){updateLocalStatus([r.id],"Paused");}}}>{r.status==="Live"?"Pause automation":r.status==="Paused"?"Activate automation":"Publish before activating"}</button></div></>}</div></div><div className="po-automation-mobile-card-badges"><span className={"po-trigger-badge "+(r.trigger==="DM keyword"?"is-message":r.trigger==="Comment or DM keywords"?"is-both":"is-comment")}>{r.trigger==="Comment"||r.trigger==="Comment or DM keywords"?<InstagramMarkIcon/>:<SendIcon/>}{r.trigger==="Comment or DM keywords"?"Comment or DM":r.trigger==="DM keyword"?"Direct message":"Comment"}</span><Tag tone={r.status==="Live"?"green":r.status==="Paused"?"blue":r.status==="Needs publishing"?"warning":"neutral"}>{r.status}</Tag></div><div className="po-automation-mobile-card-footer"><span>Updated {r.updated}</span><button type="button" onClick={()=>openRow(r)}>Open automation →</button></div></article>)}</div><div className="po-automation-desktop-table"><table className="po-automation-table"><thead><tr><th className="po-check-cell"><input type="checkbox" aria-label="Select visible automations" checked={allVisibleSelected} onChange={()=>setSelectedIds(current=>{const next=new Set(current);if(allVisibleSelected)visibleRows.forEach(r=>next.delete(r.id));else visibleRows.forEach(r=>next.add(r.id));return next;})}/></th><th>Name</th><th>Starts when</th><th>Status</th><th>Updated</th><th aria-label="Actions"></th></tr></thead><tbody>
            {visibleRows.map(r=><tr key={r.id} className={selectedIds.has(r.id)?"is-selected":""}>
              <td className="po-check-cell"><input type="checkbox" aria-label={"Select "+r.name} checked={selectedIds.has(r.id)} onChange={()=>setSelectedIds(current=>{const next=new Set(current);if(next.has(r.id))next.delete(r.id);else next.add(r.id);return next;})}/></td>
              <td><button type="button" className="po-table-primary-link" onClick={()=>openRow(r)}>{r.name}</button><small>{r.summary||r.trigger+" · sample keywords"}</small></td>
              <td><span className={"po-trigger-badge "+(r.trigger==="DM keyword"?"is-message":r.trigger==="Comment or DM keywords"?"is-both":"is-comment")}>{r.trigger==="Comment"||r.trigger==="Comment or DM keywords"?<InstagramMarkIcon/>:<SendIcon/>}{r.trigger==="Comment or DM keywords"?"Comment or DM":r.trigger==="DM keyword"?"Direct message":"Comment"}</span></td>
              <td><Tag tone={r.status==="Live"?"green":r.status==="Paused"?"blue":r.status==="Needs publishing"?"warning":"neutral"}>{r.status}</Tag></td>
              <td className="po-updated-cell">{r.updated}</td>
              <td className="po-action-cell"><div className="po-action-menu-wrap"><button type="button" className="po-icon-button" aria-label={"Actions for "+r.name} aria-expanded={openActionId===r.id} onClick={()=>setOpenActionId(current=>current===r.id?null:r.id)}><DotsVerticalIcon/></button>{openActionId===r.id&&<><button className="po-action-dismiss" type="button" aria-label="Close action menu" onClick={()=>setOpenActionId(null)}/><div className="po-action-menu" role="group" aria-label={"Actions for "+r.name}><button type="button" onClick={()=>{setOpenActionId(null);openRow(r);}}>Open</button><button type="button" onClick={()=>{setOpenActionId(null);setRenameItem(r);setRenameValue(r.name);}}>Rename</button>{r.status==="Draft"&&<button type="button" className="is-danger" onClick={()=>{setOpenActionId(null);setDeleteItem(r);}}>Delete draft</button>}<button type="button" disabled={r.status==="Draft"||r.status==="Needs publishing"} onClick={()=>{if(r.status==="Paused"){setOpenActionId(null);setConfirmSingleActivation(r);}else if(r.status==="Live"){updateLocalStatus([r.id],"Paused");}}}>{r.status==="Live"?"Pause automation":r.status==="Paused"?"Activate automation":"Publish before activating"}</button></div></>}</div></td>
            </tr>)}
          </tbody></table></div></>}
          {rows.length>0&&<div className="po-table-footer"><span>Showing {(page-1)*pageSize+1}–{Math.min(page*pageSize,rows.length)} of {rows.length} automations</span><div className="po-row-actions"><button type="button" disabled={page===1} onClick={()=>setPage(v=>Math.max(1,v-1))}>Previous</button><span>Page {page} of {pageCount}</span><button type="button" disabled={page===pageCount} onClick={()=>setPage(v=>Math.min(pageCount,v+1))}>Next</button></div></div>}
        </div>
        <p className="po-help-text">Illustrative records only. All action-menu, bulk-selection and status changes are local to this preview.</p>
      </>:<div className="po-template-grid">{templates.map((t,i)=><article className="po-template-card" key={t.name}><div className="po-template-top"><span className="po-template-number">0{i+1}</span><Tag>{t.note}</Tag></div><h2>{t.name}</h2><p>{t.outcome}</p><div className="po-template-metadata"><span><small>TRIGGER</small><strong>{t.trigger}</strong></span><span><small>FLOW</small><strong>{t.flow}</strong></span></div><button type="button" className="po-button po-button--secondary" onClick={()=>createFromTemplate(t)}>Use this template →</button></article>)}</div>}
    </div>
    {showCreate&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setShowCreate(false)}><section ref={createRef} tabIndex={-1} className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-create-draft-title"><div className="po-modal-top"><span className="po-eyebrow">NEW AUTOMATION · PREVIEW</span><button type="button" className="po-icon-button" aria-label="Close draft dialog" onClick={()=>setShowCreate(false)}>×</button></div><h2 id="po-create-draft-title">Create a draft</h2><p>Choose a clear name and start condition. This creates a local preview draft only; it doesn't create a server record.</p><label className="po-field-block">Automation name<input value={draftName} onChange={e=>setDraftName(e.target.value)} placeholder="e.g. Pricing enquiries" maxLength={100}/></label><label className="po-field-block">Start condition<select value={draftTrigger} onChange={e=>setDraftTrigger(e.target.value)}><option value="comment">Instagram comments</option><option value="message">Direct messages</option><option value="both">Comments and direct messages</option></select></label><label className="po-field-block">Keywords<textarea rows={3} value={draftKeywords} onChange={e=>setDraftKeywords(e.target.value)} placeholder="price, quote, details"/></label><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setShowCreate(false)}>Cancel</button><button type="button" className="po-button po-button--primary" disabled={!draftName.trim()||!draftKeywords.trim()} onClick={()=>{const source=draftTrigger;setShowCreate(false);onOpenBuilder(draftName.trim(),"Draft",true,{triggerType:source,keywords:draftKeywords});}}>Continue to builder</button></div></section></div>}
    {renameItem&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setRenameItem(null)}><section ref={renameRef} tabIndex={-1} className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-rename-title"><div className="po-modal-top"><span className="po-eyebrow">RENAME AUTOMATION · PREVIEW</span><button type="button" className="po-icon-button" aria-label="Close rename dialog" onClick={()=>setRenameItem(null)}>×</button></div><h2 id="po-rename-title">Rename automation</h2><label className="po-field-block">Automation name<input value={renameValue} maxLength={100} onChange={e=>setRenameValue(e.target.value)} autoFocus/></label><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setRenameItem(null)}>Cancel</button><button type="button" className="po-button po-button--primary" disabled={!renameValue.trim()} onClick={()=>{setItems(current=>current.map(item=>item.id===renameItem.id?{...item,name:renameValue.trim(),updated:"Just now"}:item));setRenameItem(null);setNotice("Automation renamed in preview only. No production record changed.");}}>Save changes</button></div></section></div>}
    {deleteItem&&<div className="po-modal-backdrop" role="presentation"><section ref={deleteRef} tabIndex={-1} className="po-modal" role="alertdialog" aria-modal="true" aria-labelledby="po-delete-title"><div className="po-modal-top"><span className="po-modal-icon po-modal-icon--warning">!</span><button type="button" className="po-icon-button" aria-label="Close delete confirmation" onClick={()=>setDeleteItem(null)}>×</button></div><span className="po-eyebrow">DELETE DRAFT · PREVIEW</span><h2 id="po-delete-title">Delete “{deleteItem.name}”?</h2><p>This removes only the illustrative inactive draft from the preview list. No production record is deleted.</p><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setDeleteItem(null)}>Cancel</button><button type="button" className="po-button po-button--danger" onClick={()=>{setItems(current=>current.filter(item=>item.id!==deleteItem.id));setSelectedIds(current=>{const next=new Set(current);next.delete(deleteItem.id);return next;});setDeleteItem(null);setPage(1);setNotice("Illustrative draft removed from this preview only.");}}>Delete draft</button></div></section></div>}
    {confirmSingleActivation&&<div className="po-modal-backdrop" role="presentation"><section ref={activateRef} tabIndex={-1} className="po-modal" role="alertdialog" aria-modal="true" aria-labelledby="po-single-activate-title"><div className="po-modal-top"><span className="po-modal-icon po-modal-icon--warning">!</span><button type="button" className="po-icon-button" aria-label="Close activation confirmation" onClick={()=>setConfirmSingleActivation(null)}>×</button></div><span className="po-eyebrow">ACTIVATION · PREVIEW</span><h2 id="po-single-activate-title">Activate “{confirmSingleActivation.name}”?</h2><p>Activation would start automated replies to matching Instagram conversations in production. This preview only changes the status badge in the sample list.</p><div className="po-warning-note"><span>!</span><span><strong>Preview only</strong><small>No account is enabled and no message is sent.</small></span></div><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setConfirmSingleActivation(null)}>Cancel</button><button type="button" className="po-button po-button--primary" onClick={()=>{updateLocalStatus([confirmSingleActivation.id],"Live");setConfirmSingleActivation(null);}}>Activate in preview</button></div></section></div>}
    {bulkAction&&<div className="po-modal-backdrop" role="presentation"><section ref={bulkRef} tabIndex={-1} className="po-modal" role="alertdialog" aria-modal="true" aria-labelledby="po-bulk-title"><div className="po-modal-top"><span className="po-modal-icon po-modal-icon--warning">!</span><button type="button" className="po-icon-button" aria-label="Close bulk confirmation" onClick={()=>setBulkAction(null)}>×</button></div><h2 id="po-bulk-title">{bulkAction==="activate"?"Activate selected automations?":"Pause selected automations?"}</h2><p>{bulkAction==="activate"?eligibleToActivate.length+" published paused automation(s) will be marked Live in the sample list. Drafts cannot be activated until published.":eligibleToPause.length+" live automation(s) will be marked Paused in the sample list."}</p><div className="po-warning-note"><span>!</span><span><strong>Preview only</strong><small>No Instagram replies are enabled or disabled.</small></span></div><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setBulkAction(null)}>Cancel</button><button type="button" className="po-button po-button--primary" onClick={()=>updateLocalStatus((bulkAction==="activate"?eligibleToActivate:eligibleToPause).map(r=>r.id),bulkAction==="activate"?"Live":"Paused")}>{bulkAction==="activate"?"Activate in preview":"Pause in preview"}</button></div></section></div>}
  </section>;
}

export function LeadDetailScreen({leadName,leadHandle,initialStage,initialOwner,initialHandoff,onBack,onNavigate}:{leadName:string;leadHandle:string;initialStage:string;initialOwner:string;initialHandoff:boolean;onBack:()=>void;onNavigate:Go}) {
  const [tab,setTab]=useState(() => {
    const requested = new URLSearchParams(window.location.search).get("leadTab");
    return requested && ["Overview","Conversation","Activities","Notes"].includes(requested) ? requested : "Overview";
  }); const [stage,setStage]=useState(initialStage); const [owner,setOwner]=useState(initialOwner==="Unassigned"?"Needs assignment":initialOwner); const [handoff,setHandoff]=useState(initialHandoff); const [notes,setNotes]=useState(""); const [savedNotes,setSavedNotes]=useState<string[]>([]); const [showScore,setShowScore]=useState(false); const [tagInput,setTagInput]=useState(""); const [tags,setTags]=useState(["Interested"]); const [notice,setNotice]=useState(""); const [dealOpen,setDealOpen]=useState(false); const [dealValue,setDealValue]=useState("25000");
  return <section className="po-lead-detail-screen"><div className="po-lead-detail-toolbar"><button type="button" className="po-button po-button--quiet" aria-label="Back to leads" onClick={onBack}>← Back to leads</button><div className="po-lead-profile-heading"><span className="po-avatar po-avatar--large">{leadName.split(" ").map(n=>n[0]).slice(0,2).join("")}</span><div><h2>{leadName}</h2><p>{leadHandle} · Instagram lead · sample record</p></div><Tag tone={handoff?"blue":"purple"}>{handoff?"Human is replying":"AI handling"}</Tag></div><button type="button" className="po-button po-button--secondary" onClick={()=>setHandoff(v=>!v)}>{handoff?"Return to AI (demo)":"Take over (demo)"}</button></div>
    <div className="po-lead-tabs" role="tablist" aria-label="Lead detail sections">{["Overview","Conversation","Activities","Notes"].map((t,index)=><button type="button" role="tab" id={"po-lead-tab-"+t.toLowerCase()} aria-controls="po-lead-tabpanel" aria-selected={tab===t} tabIndex={tab===t?0:-1} className={tab===t?"is-active":""} key={t} onKeyDown={event=>{let nextIndex:number|null=null;if(event.key==="ArrowRight")nextIndex=(index+1)%4;if(event.key==="ArrowLeft")nextIndex=(index+3)%4;if(event.key==="Home")nextIndex=0;if(event.key==="End")nextIndex=3;if(nextIndex!==null){event.preventDefault();const tabButtons=Array.from(event.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>('[role="tab"]')??[]);tabButtons[nextIndex]?.focus();tabButtons[nextIndex]?.click();}}} onClick={()=>setTab(t)}>{t}</button>)}</div>
    <div id="po-lead-tabpanel" role="tabpanel" aria-labelledby={"po-lead-tab-"+tab.toLowerCase()} tabIndex={0}>
    {tab==="Overview"&&<div className="po-detail-grid"><div className="po-detail-main"><Panel><PanelTitle title="Lead details" description="Business-friendly fields and clear ownership."/><div className="po-detail-fields"><label>Pipeline stage<select value={stage} onChange={e=>setStage(e.target.value)}>{["New","Contacted","Qualified","Meeting Scheduled","Won","Lost"].map(s=><option key={s}>{s}</option>)}</select></label><label>Owner<select value={owner} onChange={e=>setOwner(e.target.value)}>{["Needs assignment","Alex Morgan","Sam Taylor","Queue — Sales follow-up"].map(s=><option key={s}>{s}</option>)}</select></label><label>Source<span className="po-readonly-field">Instagram comment</span></label><label>Last activity<span className="po-readonly-field">2 minutes ago · sample</span></label></div>{handoff&&owner==="Needs assignment"&&<div className="po-warning-note"><span>!</span><span><strong>Needs assignment</strong><small>This lead is in human handling but has no owner. Assign a teammate or a follow-up queue.</small></span></div>}</Panel>
    <Panel><PanelTitle title="Captured facts" description="Information collected during the conversation."/><div className="po-captured-facts"><div><span>Interest</span><strong>1:1 coaching</strong></div><div><span>Preferred timeline</span><strong>Within this month</strong></div></div><div className="po-tag-editor">{tags.map(tag=><button type="button" key={tag} className="po-tag-removable" onClick={()=>setTags(v=>v.filter(x=>x!==tag))}><Tag>{tag} ×</Tag></button>)}</div><div className="po-inline-add"><input value={tagInput} onChange={e=>setTagInput(e.target.value)} placeholder="Add lead tag" aria-label="Add lead tag"/><button type="button" className="po-button po-button--secondary" disabled={!tagInput.trim()} onClick={()=>{setTags(v=>v.concat(tagInput.trim()));setTagInput("");}}>Add tag</button></div><button type="button" className="po-text-action" onClick={()=>onNavigate("settings")}>Manage captured fields →</button></Panel>
    <Panel><PanelTitle title="Lead intelligence" description="Explain score, signals, and calculation time." action={<Tag>Not calculated</Tag>}/><p className="po-panel-copy">No score is available for this sample lead yet. In the live product, scoring requires configured rules and enough conversation signals. This preview does not call scoring services or consume tokens.</p><button type="button" className="po-button po-button--secondary" aria-expanded={showScore} onClick={()=>setShowScore(v=>!v)}>{showScore?"Hide scoring explanation":"Why is there no score yet?"}</button>{showScore&&<div className="po-definition-block"><strong>What is required for a score</strong><ol><li>At least one applicable scoring rule is configured in Settings → Scoring.</li><li>The conversation contains supported signals, such as stated interest, need, budget, location, or completed qualification goals.</li><li>The scoring calculation completes successfully.</li></ol><p>In production, show the calculation time and the rules that contributed to the score. This preview intentionally does not calculate a score.</p></div>}</Panel>
    <Panel><PanelTitle title="Deals" description="Potential revenue associated with this lead."/><div className="po-empty-detail"><strong>No deal linked</strong><span>Illustrate deal value without creating real sales records.</span></div>{dealOpen?<div className="po-add-field"><label>Estimated value (INR)<input inputMode="numeric" value={dealValue} onChange={e=>setDealValue(e.target.value)}/></label><button type="button" className="po-button po-button--primary" onClick={()=>{setNotice("Example deal ₹"+dealValue+" recorded in local preview state only.");setDealOpen(false);}}>Add example deal</button></div>:<button type="button" className="po-button po-button--secondary" onClick={()=>setDealOpen(true)}>Add deal (preview)</button>}</Panel></div><aside className="po-detail-aside"><Panel><h2>Contact</h2><p>{leadHandle}</p><div className="po-detail-row"><span>Handoff</span><Tag tone={handoff?"blue":"purple"}>{handoff?"Human":"AI"}</Tag></div><div className="po-detail-row"><span>Owner</span><strong>{owner}</strong></div><div className="po-detail-row"><span>Stage</span><Tag>{stage}</Tag></div><button type="button" className="po-button po-button--secondary po-full-width" onClick={()=>onNavigate("inbox")}>Open Inbox</button></Panel><Panel><PanelTitle title="Recent activity"/><div className="po-timeline"><div><b>Lead created</b><small>Trigger matched · Today 10:24 AM</small></div><div><b>AI reply recorded</b><small>Example reply · 10:25 AM</small></div></div></Panel></aside></div>}
    {tab==="Conversation"&&<Panel><PanelTitle title="Conversation history" description="Sample timeline · not connected to a live Instagram thread."/><div className="po-messages"><div className="po-message po-message--incoming"><span>Hi, do you have pricing for 1:1 coaching?</span><small>10:24 AM · Sample</small></div><div className="po-message po-message--outgoing"><span>Thanks for reaching out. What are you hoping to achieve?</span><small>10:25 AM · Example AI reply</small></div><div className="po-message po-message--incoming"><span>I'd like to build a routine before the end of the month.</span><small>10:26 AM · Sample</small></div></div><button type="button" className="po-button po-button--secondary" onClick={()=>onNavigate("inbox")}>Open Inbox →</button></Panel>}
    {tab==="Activities"&&<Panel><PanelTitle title="Activity history" description="Actions and state changes for this sample lead."/><div className="po-timeline"><div><b>Lead created</b><small>Comment trigger matched · 10:24 AM</small></div><div><b>AI reply recorded</b><small>Example response · 10:25 AM</small></div><div><b>Qualification captured</b><small>Interest and timeline · 10:26 AM</small></div><div><b>Human follow-up requested</b><small>Owner assignment pending · 10:30 AM</small></div></div></Panel>}
    {tab==="Notes"&&<Panel><PanelTitle title="Team notes" description="Leave context for the next person handling this conversation."/><p className="po-panel-copy">Notes stay local to this preview and clear on refresh.</p><label className="po-field-block">Add a note<textarea rows={4} value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Add context for the next teammate…"/></label><button type="button" className="po-button po-button--primary" disabled={!notes.trim()} onClick={()=>{setSavedNotes(v=>[notes,...v]);setNotes("");}}>Add note</button>{savedNotes.map((n,i)=><div className="po-note-card" key={i}><strong>Sample note · just now</strong><p>{n}</p></div>)}</Panel>}
    </div>
    {notice&&<div className="po-inline-notice" role="status">{notice}</div>}
  </section>;
}

export function KnowledgeScreen() {
  const [query,setQuery]=useState(""); const [question,setQuestion]=useState(""); const [tested,setTested]=useState(false); const [upload,setUpload]=useState(false); const [selected,setSelected]=useState("pricing-faq.md");
  const all=[{name:"pricing-faq.md",type:"Markdown",size:"18 KB",status:"Ready",updated:"Today, 09:14",tone:"green",summary:"Pricing, packages, coaching options, and service boundaries.",preview:["1:1 coaching pricing and package options","What each package includes and who it is for","Service boundaries and when to route a question to a person"]},{name:"class-schedule.pdf",type:"PDF",size:"420 KB",status:"Ready",updated:"Yesterday",tone:"green",summary:"Class times, beginner sessions, and booking information.",preview:["Beginner session times and class schedule","Booking information and session availability","Guidance for choosing a beginner-friendly session"]},{name:"brand-voice.md",type:"Markdown",size:"8 KB",status:"Needs review",updated:"Oct 09",tone:"amber",summary:"Tone, prohibited promises, and escalation guidance.",preview:["Preferred tone and response style","Promises and claims the assistant must avoid","When a conversation should be escalated"]},{name:"catalog-2026.pdf",type:"PDF",size:"Processing",status:"Processing",updated:"Just now",tone:"blue",summary:"Product details and current availability.",preview:["Product details are still being indexed","Availability evidence will appear after processing completes"]},{name:"old-faq.txt",type:"Text",size:"12 KB",status:"Failed",updated:"Oct 07",tone:"red",summary:"Parsing failed. Replace or retry before using.",preview:[] }];
  const rows=all.filter(s=>s.name.toLowerCase().includes(query.toLowerCase())); const current=rows.find(s=>s.name===selected)??all.find(s=>s.name===selected);
  return <section className="po-knowledge-screen"><div className="po-kb-layout"><Panel className="po-kb-sources"><PanelTitle title="Knowledge sources" description="Ready sources ground AI replies. Processing sources are not ready; failed sources are excluded." action={<button type="button" className="po-button po-button--primary" onClick={()=>setUpload(v=>!v)}><PlusIcon/> Add source</button>}/><label className="po-search"><SearchIcon/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search source files" aria-label="Search source files"/></label>{upload&&<div className="po-upload-zone"><strong>Add a knowledge source</strong><p>PDF, Markdown, or plain text. This preview does not upload or index files.</p><input type="file" accept=".pdf,.md,.txt" aria-label="Choose a sample file"/><button type="button" className="po-button po-button--secondary" onClick={()=>setUpload(false)}>Close</button></div>}<div className="po-source-list">{rows.map(s=><button type="button" className={"po-source-row"+(selected===s.name?" is-selected":"")} key={s.name} onClick={()=>{setSelected(s.name);setTested(false);}}><span className="po-source-type">{s.type==="PDF"?"PDF":s.type==="Text"?"TXT":"MD"}</span><span><strong>{s.name}</strong><small>{s.type} · {s.size} · Updated {s.updated}</small><span className="po-source-summary">{s.summary}</span></span><Tag tone={s.tone}>{s.status}</Tag></button>)}</div>{rows.length===0&&<div className="po-table-empty"><strong>No files match</strong><span>Try a different source name.</span></div>}</Panel><aside className="po-content-panel po-kb-inspector"><span className="po-eyebrow">SOURCE DETAILS</span>{current&&<><h2>{current.name}</h2><p>{current.summary}</p><div className="po-detail-row"><span>Index status</span><Tag tone={current.tone}>{current.status}</Tag></div><div className="po-detail-row"><span>Last processed</span><strong>{current.updated}</strong></div><div className="po-detail-row"><span>Extracted sections</span><strong>{current.status==="Failed"?"Unavailable":current.status==="Processing"?"Pending":"3 · sample"}</strong></div>{current.status==="Failed"?<div className="po-warning-note"><span>!</span><span><strong>Source isn't being used</strong><small>Replace the file or retry processing. No extraction runs here.</small></span></div>:<div className="po-definition-block"><strong>Extracted content preview</strong>{current.status==="Processing"?<p>Processing is still in progress. Extracted content will appear here once indexing is complete.</p>:<ul>{current.preview.map((item)=><li key={item}>{item}</li>)}</ul>}<small>Representative sample excerpts for this preview; production should display the actual parsed source evidence.</small></div>}</>}</aside></div><Panel className="po-retrieval-test"><PanelTitle eyebrow="RETRIEVAL CHECK" title="Test a question against knowledge" description="Verify source relevance before using it in a live reply."/><div id="po-test-question" className="po-test-question"><label>Question<input value={question} onChange={e=>{setQuestion(e.target.value);setTested(false);}} placeholder="e.g. What are the 1:1 coaching prices?"/></label><button type="button" className="po-button po-button--primary" disabled={!question.trim()} onClick={()=>setTested(true)}>Test question</button></div>{tested&&<div className="po-test-result" role="status"><Tag tone="success">Illustrative result</Tag><div><strong>Potential source: {current?.name??"none selected"}</strong><p>No retrieval service was called. Production should show source excerpts and confidence.</p></div></div>}</Panel></section>;
}

export function ContentScreen() {
  const [filter,setFilter]=useState("All media"); const [query,setQuery]=useState(""); const [preview,setPreview]=useState<string|null>(null); const [refreshed,setRefreshed]=useState(false);
  const contentRef = useModalDialog(Boolean(preview), () => setPreview(null));
  const items=[{id:"p1",type:"Image",title:"Spring coaching offer",caption:"New to training? Start with a plan that fits your week.",comments:42,keywords:"price · coaching · plan",updated:"Synced 8 min ago",art:"coaching"},{id:"p2",type:"Carousel",title:"What to expect in week one",caption:"A simple routine, practical guidance, and measurable progress.",comments:28,keywords:"beginner · routine · details",updated:"Synced 8 min ago",art:"routine"},{id:"p3",type:"Video",title:"A quick look at the studio",caption:"Here is what a first session looks like.",comments:17,keywords:"studio · session",updated:"Synced 11 min ago",art:"studio"}].filter(item=>(filter==="All media"||item.type===filter)&&(item.title+" "+item.caption+" "+item.keywords).toLowerCase().includes(query.toLowerCase()));
  return <section className="po-content-screen"><div className="po-screen-toolbar"><div className="po-filter-tabs" role="group" aria-label="Filter content by type">{["All media","Image","Carousel","Video"].map(v=><button type="button" className={filter===v?"is-active":""} key={v} onClick={()=>setFilter(v)}>{v}</button>)}</div><label className="po-search"><SearchIcon/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search captions and keywords" aria-label="Search content by caption or keyword"/></label></div><div className="po-content-status-line"><span>Sample Instagram account · @creatorstudio</span><button type="button" className="po-text-action" onClick={()=>setRefreshed(true)}>Refresh posts ↻</button><span role="status">{refreshed?"Sample refresh checked just now":"Last sync appears on each card"}</span></div><div className="po-content-cards">{items.map(item=><article className="po-post-card" key={item.id}><button type="button" className={"po-post-art po-post-art--"+item.art} onClick={()=>setPreview(item.id)} aria-label={"Preview "+item.title}><span className="po-post-art-label">{item.type.toUpperCase()} · SAMPLE ART</span><strong>{item.title}</strong><span className="po-post-art-bottom">@creatorstudio <InstagramMarkIcon/></span></button><div className="po-post-body"><div className="po-post-meta"><Tag>{item.type}</Tag><span>{item.updated}</span></div><h2>{item.title}</h2><p>{item.caption}</p><div className="po-post-context-row"><span>{item.comments} comments</span><span>Trigger terms: {item.keywords}</span></div><div className="po-post-actions"><button type="button" className="po-button po-button--secondary" onClick={()=>setPreview(item.id)}>Preview post</button><button type="button" className="po-button po-button--quiet" onClick={()=>setPreview(item.id)}>Review comments →</button></div></div></article>)}</div>{items.length===0&&<div className="po-table-empty"><strong>No posts match</strong><span>Change the media filter or search term.</span></div>}{preview&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setPreview(null)}><section ref={contentRef} tabIndex={-1} className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-content-modal-title"><div className="po-modal-top"><span className="po-eyebrow">POST PREVIEW · SAMPLE</span><button type="button" className="po-icon-button" aria-label="Close post preview" onClick={()=>setPreview(null)}>×</button></div>{(()=>{const item=items.find(v=>v.id===preview);return item?<><div className={"po-post-art po-post-art--"+item.art}><span className="po-post-art-label">{item.type.toUpperCase()} · SAMPLE ART</span><strong>{item.title}</strong></div><h2 id="po-content-modal-title">{item.title}</h2><p>{item.caption}</p><div className="po-detail-row"><span>Comments</span><strong>{item.comments} · sample</strong></div><div className="po-detail-row"><span>Trigger terms</span><strong>{item.keywords}</strong></div></>:null;})()}<div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setPreview(null)}>Close</button></div></section></div>}</section>;
}

export function AnalyticsScreen() {
  const [tab,setTab]=useState(() => new URLSearchParams(window.location.search).get("analyticsTab")==="Conversion" ? "Conversion" : "Activity"); const [period,setPeriod]=useState("Last 7 days"); const [definitions,setDefinitions]=useState(false);
  return <section className="po-analytics-screen"><div className="po-analytics-controls"><div className="po-tab-bar" role="tablist" aria-label="Analytics views"><button type="button" role="tab" id="po-analytics-tab-activity" aria-controls="po-analytics-panel" aria-selected={tab==="Activity"} className={tab==="Activity"?"is-active":""} onClick={()=>setTab("Activity")}>Activity volume</button><button type="button" role="tab" id="po-analytics-tab-conversion" aria-controls="po-analytics-panel" aria-selected={tab==="Conversion"} className={tab==="Conversion"?"is-active":""} onClick={()=>setTab("Conversion")}>Lead conversion</button></div><label className="po-select-wrap"><span className="po-visually-hidden">Analytics date range</span><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Last 7 days</option><option>Last 30 days</option><option>This month</option><option>All time</option></select><ChevronDownIcon/></label></div>
    <div id="po-analytics-panel" role="tabpanel" aria-labelledby={tab==="Activity"?"po-analytics-tab-activity":"po-analytics-tab-conversion"}>
    {tab==="Activity"?<><div className="po-metric-row"><Metric label="Comments received" value="10" note={"in "+period.toLowerCase()}/><Metric label="Direct messages" value="154" note="inbound event count"/><Metric label="Replies sent" value="128" note="sample events"/><Metric label="Human handoffs" value="7" note="sample routing events"/></div><Panel><PanelTitle eyebrow="INBOUND ACTIVITY" title="Messages and comments over time" description="Events can repeat from the same lead; these are not conversion rates."/><div className="po-minibars" role="img" aria-label="Illustrative activity over seven days">{[18,24,17,26,33,22,24].map((n,i)=><div className="po-minibar-col" key={i}><b className="po-minibar-value">{n}</b><div className="po-minibar-track"><span style={{height:n/33*100+"%"}}/></div><small>{["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][i]}</small></div>)}</div><div className="po-data-table-scroll"><table className="po-automation-table"><thead><tr><th>Event type</th><th>Count</th><th>Definition</th></tr></thead><tbody><tr><td>Comments received</td><td>10</td><td>Inbound comment events</td></tr><tr><td>Direct messages</td><td>154</td><td>Inbound DM events, including repeats</td></tr><tr><td>Replies sent</td><td>128</td><td>AI or team replies recorded</td></tr><tr><td>Human handoffs</td><td>7</td><td>Conversation control routed to a person</td></tr></tbody></table></div></Panel></>:<><div className="po-metric-row"><Metric label="Unique leads" value="24" note="sample pipeline"/><Metric label="Qualified" value="2" note="8.3% of leads"/><Metric label="Contacted" value="3" note="12.5% of leads"/><Metric label="Won" value="0" note="none in sample"/></div><Panel><PanelTitle eyebrow="CURRENT PIPELINE" title="Lead stage distribution" description="Unique lead records by current stage; totals reconcile to 24."/><div className="po-stage-list po-stage-list--large">{[["New",19,"79%"],["Contacted",3,"13%"],["Qualified",2,"8%"],["Won",0,"0%"]].map(([name,n,p])=><div className="po-stage-row" key={name as string}><span>{name}</span><div className="po-stage-track"><span style={{width:p as string}}/></div><strong>{n}</strong><Tag>{p}</Tag></div>)}</div></Panel></>}
    <button type="button" className="po-help-text" onClick={()=>setDefinitions(v=>!v)}>{definitions?"Hide definitions ↑":"Show metric definitions and attribution ↓"}</button>{definitions&&<div className="po-definition-block"><strong>Reporting definitions</strong><p>All values are illustrative. Activity counts events, while conversion counts unique lead records. Never express raw activity events as a percentage of leads without an explicit denominator and attribution rule.</p></div>}
    <div className="po-overview-grid"><Panel><PanelTitle title="Top performing posts" description="Posts ranked by sample comment activity."/><div className="po-data-table-scroll"><table className="po-automation-table"><thead><tr><th>Post</th><th>Comments</th></tr></thead><tbody><tr><td>Spring coaching offer</td><td>16</td></tr><tr><td>Week one guide</td><td>2</td></tr></tbody></table></div></Panel><Panel><PanelTitle title="Top trigger keywords" description="Counts show trigger matches, not lead conversions."/><div className="po-keyword-list">{[["ongoing conversation",112],["product",17],["signalAI",8],["details",7],["nice",5]].map(([w,n])=><div key={w as string}><span>{w}</span><strong>{n}</strong></div>)}</div></Panel></div></div>
  </section>;
}

export function IntegrationsScreen() {
  const [dialog,setDialog]=useState<"connect"|"disconnect"|null>(null); const [notice,setNotice]=useState(""); const [advanced,setAdvanced]=useState(false);
  const integrationsRef = useModalDialog(Boolean(dialog), () => setDialog(null));
  return <section><div className="po-integration-health"><span className="po-health-ring"><CheckCircleIcon/></span><div><strong>Preview account state</strong><p>This is an illustrative Instagram account card. The preview is not connected to Instagram or your production workspace.</p></div><Tag tone="neutral">Preview only</Tag></div><Panel><div className="po-integration-card-header"><span className="po-integration-brand"><InstagramMarkIcon/></span><div><span className="po-eyebrow">INSTAGRAM BUSINESS · SAMPLE</span><h2>@creatorstudio</h2><p>Example account identity · not a live connection</p></div><Tag tone="neutral">Sample account</Tag><button type="button" className="po-button po-button--secondary" onClick={()=>setNotice("A real OAuth flow is not started from this preview. No Instagram account was contacted.")}>Simulate add account</button><button type="button" className="po-button po-button--quiet" onClick={()=>setDialog("connect")}>Simulate health check</button></div><div className="po-health-grid"><div><span>Permissions</span><strong><Tag>Illustrative</Tag></strong><small>Messaging + comments shown as sample scopes</small></div><div><span>Webhook</span><strong><Tag>Example</Tag></strong><small>No webhook delivery is occurring from this preview</small></div><div><span>Token status</span><strong>Sample value</strong><small>No production token is loaded</small></div><div><span>Assigned automations</span><strong>3 · sample</strong><small>Shown for design validation only</small></div></div><button type="button" className="po-text-action" onClick={()=>setAdvanced(v=>!v)}>{advanced?"Hide technical details ↑":"Show technical details ↓"}</button>{advanced&&<div className="po-definition-block"><strong>Advanced account details</strong><p>Account IDs, tokens, permissions, webhook events, and business scopes are placeholders. The preview never reuses production credentials.</p></div>}</Panel><div className="po-secondary-integrations"><Panel><Tag>Coming soon</Tag><h2>WhatsApp</h2><p>Not enabled in this product preview.</p><button disabled className="po-button po-button--secondary">Not available</button></Panel><Panel><Tag>Coming soon</Tag><h2>CRM sync</h2><p>External CRM sync is not enabled in this preview.</p><button disabled className="po-button po-button--secondary">Not available</button></Panel></div>{notice&&<div className="po-inline-notice" role="status">{notice}</div>}{dialog&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setDialog(null)}><section ref={integrationsRef} tabIndex={-1} className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-integrations-modal"><div className="po-modal-top"><span className="po-eyebrow">ACCOUNT ACTION · PREVIEW</span><button type="button" className="po-icon-button" aria-label="Close" onClick={()=>setDialog(null)}>×</button></div><h2 id="po-integrations-modal">{dialog==="disconnect"?"Disconnect sample account?":"Run a sample connection check?"}</h2><p>{dialog==="disconnect"?"A live disconnect can stop automations. This preview has no connected account, so nothing will be disconnected.":"A real check would validate permissions, token health, webhook delivery, and the last event. No external check runs here."}</p><div className="po-modal-footer"><button type="button" className="po-button po-button--secondary" onClick={()=>setDialog(null)}>Cancel</button><button type="button" className="po-button po-button--primary" onClick={()=>{setNotice(dialog==="disconnect"?"No account is connected in this preview; nothing changed.":"Sample health check completed. No external account was contacted.");setDialog(null);}}>Show outcome</button></div></section></div>}</section>;
}

export function TeamScreen() {
  const [inviteOpen,setInviteOpen]=useState(false); const [email,setEmail]=useState(""); const [role,setRole]=useState("member"); const [notice,setNotice]=useState(""); const [pending,setPending]=useState(true);
  const inviteRef = useModalDialog(inviteOpen, () => setInviteOpen(false));
  return <section><div className="po-team-summary"><div><span className="po-eyebrow">WORKSPACE MEMBERS</span><h2>People with access</h2><p>Sample roles and permission details.</p></div><button type="button" className="po-button po-button--primary" onClick={()=>setInviteOpen(true)}><PlusIcon/> Invite teammate</button></div><Panel><div className="po-team-row"><span className="po-avatar">CS</span><div><strong>owner@creatorstudio.example</strong><small>Workspace owner · sample</small></div><Tag tone="purple">Owner</Tag><span className="po-team-permissions">All settings and billing</span></div><div className="po-team-row"><span className="po-avatar">AM</span><div><strong>alex@creatorstudio.example</strong><small>Joined Sep 18 · sample</small></div><Tag>Member</Tag><span className="po-team-permissions">Inbox, leads, automations</span><button className="po-button po-button--quiet" type="button" onClick={()=>setNotice("Role editing is demonstration-only; nothing was saved.")}>Manage</button></div>{pending&&<div className="po-team-row"><span className="po-avatar">JT</span><div><strong>jordan@creatorstudio.example</strong><small>Invitation pending · sent yesterday</small></div><Tag tone="warning">Pending</Tag><span className="po-team-permissions">Member invite</span><div className="po-row-actions"><button type="button" onClick={()=>setNotice("No invitation email was sent in preview.")}>Resend</button><button type="button" onClick={()=>setPending(false)}>Cancel invite</button></div></div>}</Panel><Panel><PanelTitle title="Role permissions" description="Show what each role can manage before granting access."/><div className="po-permission-table"><div className="po-permission-row po-permission-row--header"><span>Capability</span><span>Owner</span><span>Admin</span><span>Member</span></div>{[["Reply to conversations","Yes","Yes","Yes"],["Edit automations","Yes","Yes","Limited"],["Manage integrations","Yes","Yes","No"],["Invite teammates","Yes","Yes","No"],["Manage billing","Yes","No","No"]].map(row=><div key={row[0]} className="po-permission-row">{row.map((v,i)=><span key={i}>{v}</span>)}</div>)}</div></Panel>{notice&&<div className="po-inline-notice" role="status">{notice}</div>}{inviteOpen&&<div className="po-modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setInviteOpen(false)}><section ref={inviteRef} tabIndex={-1} className="po-modal" role="dialog" aria-modal="true" aria-labelledby="po-invite-title"><div className="po-modal-top"><span className="po-eyebrow">WORKSPACE ACCESS</span><button type="button" className="po-icon-button" aria-label="Close invite dialog" onClick={()=>setInviteOpen(false)}>×</button></div><h2 id="po-invite-title">Invite a teammate</h2><p>The live product sends an invitation; this preview only checks the form.</p><label className="po-field-block">Email address<input value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="teammate@company.com"/></label><label className="po-field-block">Role<select value={role} onChange={e=>setRole(e.target.value)}><option value="member">Member</option><option value="admin">Admin</option></select></label><div className="po-modal-footer"><button className="po-button po-button--secondary" type="button" onClick={()=>setInviteOpen(false)}>Cancel</button><button className="po-button po-button--primary" type="button" disabled={!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)} onClick={()=>{setNotice("Invitation preview prepared for "+email+" as "+role+". No email sent.");setInviteOpen(false);setEmail("");}}>Review invitation</button></div></section></div>}</section>;
}

export function BillingScreen() {
  const [notice,setNotice]=useState(""); const [showLimits,setShowLimits]=useState(false);
  return <section><div className="po-plan-state"><div><span className="po-eyebrow">CURRENT PLAN</span><h2>Trial</h2><p>Example beta workspace · billing isn't configured in this preview.</p></div><Tag tone="warning">Trial · sample</Tag></div><div className="po-billing-grid"><Panel><PanelTitle title="AI token usage" description="Tokens consumed by supported AI operations."/><div className="po-usage-value"><strong>145,474</strong><span>/ 200,000 tokens</span></div><div className="po-usage-track"><span style={{width:"72.7%"}}/></div><div className="po-usage-meta"><span>72.7% used</span><span>Reset date not configured</span></div></Panel><Panel><PanelTitle title="Direct messages" description="Outbound DMs against the illustrative plan cap."/><div className="po-usage-value"><strong>66</strong><span>/ 200 messages</span></div><div className="po-usage-track"><span style={{width:"33%"}}/></div><div className="po-usage-meta"><span>33% used</span><span>Reset date not configured</span></div></Panel></div><Panel><PanelTitle title="What happens at the limit?" description="The cap policy should be understandable before the workspace reaches it." action={<button className="po-text-action" type="button" onClick={()=>setShowLimits(v=>!v)}>{showLimits?"Hide detail ↑":"View details ↓"}</button>}/>{showLimits&&<div className="po-definition-block"><strong>Production requirements</strong><p>State whether automations pause, whether human replies remain possible, which admins are warned, and when quotas reset. The preview doesn't infer this policy.</p></div>}<div className="po-billing-facts"><div><span>Plan renewal</span><strong>Not configured</strong></div><div><span>Payment method</span><strong>Not configured</strong></div><div><span>Invoices</span><strong>No billing data</strong></div></div><div className="po-billing-actions"><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("Upgrade isn't enabled in this preview. No payment was started.")}>Explore upgrade</button><span>No payment flow is connected.</span></div></Panel>{notice&&<div className="po-inline-notice" role="status">{notice}</div>}</section>;
}

type WorkspaceSection = "General" | "Team & access" | "Plan & billing" | "Lead fields" | "AI behavior" | "Forbidden topics" | "Escalation" | "Scoring";
type PersonalSection = "Appearance" | "Profile" | "Notifications";
type SettingsSection = WorkspaceSection | PersonalSection;
const workspaceSections: WorkspaceSection[] = ["General","Team & access","Plan & billing","Lead fields","AI behavior","Forbidden topics","Escalation","Scoring"];
const personalSections: PersonalSection[] = ["Appearance","Profile","Notifications"];
const appearancePalettes: { value: PreviewPalette; label: string; description: string }[] = [
  { value: "navy-cobalt", label: "Navy & Cobalt", description: "Clear, confident blue" },
  { value: "teal-emerald", label: "Teal & Emerald", description: "Calm and approachable" },
  { value: "slate-cyan", label: "Slate & Cyan", description: "Neutral with a crisp accent" },
  { value: "forest-slate", label: "Forest & Slate", description: "Grounded green" },
  { value: "orange-amber", label: "Orange & Amber", description: "Warm and energetic" },
  { value: "neutral-slate", label: "Neutral Slate", description: "Low-colour and understated" },
  { value: "ocean-sky", label: "Ocean & Sky", description: "Deep blue with a clear sky accent" },
  { value: "jade-mint", label: "Jade & Mint", description: "Fresh green with mint highlights" },
  { value: "rose-slate", label: "Rose & Slate", description: "Warm rose on a cool neutral base" },
  { value: "amber-graphite", label: "Amber & Graphite", description: "Warm accent on charcoal neutrals" },
];

export function SettingsScreen({ theme="light", palette="navy-cobalt", onChangeTheme=()=>{}, onChangePalette=()=>{} }: {
  theme?: "light" | "dark";
  palette?: PreviewPalette;
  onChangeTheme?: (theme: "light" | "dark") => void;
  onChangePalette?: (palette: PreviewPalette) => void;
} = {}) {
  const [section,setSection] = useState<SettingsSection>(() => {
    const params = new URLSearchParams(window.location.search);
    const screen = params.get("screen");
    const requested = params.get("settingsSection") ?? (screen === "team" ? "Team & access" : screen === "billing" ? "Plan & billing" : null);
    const normalized = requested === "Fields" ? "Lead fields" : requested;
    return normalized && [...workspaceSections,...personalSections].includes(normalized as SettingsSection) ? normalized as SettingsSection : "Team & access";
  });
  const [notice,setNotice] = useState("");
  const [generalName,setGeneralName] = useState("Creator Studio");
  const [generalTimezone,setGeneralTimezone] = useState("Asia/Kolkata");
  const [generalOwner,setGeneralOwner] = useState("First available teammate");
  const [profileName,setProfileName] = useState("Alex Morgan");
  const [profileEmail,setProfileEmail] = useState("alex@creatorstudio.example");
  const [profileRole] = useState("Member");
  const [digest,setDigest] = useState(true);
  const [failureAlerts,setFailureAlerts] = useState(true);
  const [handoffAlerts,setHandoffAlerts] = useState(true);
  const [leadAlerts,setLeadAlerts] = useState(false);
  const [newField,setNewField] = useState("");
  const [fieldType,setFieldType] = useState("Text");
  const [ai,setAi] = useState("Be honest. If the knowledge source doesn't contain an answer, ask a follow-up or route to a teammate.");
  const [forbidden,setForbidden] = useState("Medical diagnosis, guaranteed outcomes, private customer data");
  const [escalation,setEscalation] = useState("Refund request, complaint, low confidence, request to speak with a person");
  const [rule,setRule] = useState("Clear purchase intent");
  const [score,setScore] = useState("20");

  const chooseSection = (next: SettingsSection) => {
    setSection(next);
    setNotice("");
    const params = new URLSearchParams(window.location.search);
    params.set("preview","precision-operations");
    params.set("screen","settings");
    params.set("settingsSection",next);
    window.history.replaceState(null,"",window.location.pathname+"?"+params.toString());
  };

  return <section className="po-settings-page">
    <div className="po-settings-layout">
      <nav className="po-settings-nav" aria-label="Settings sections">
        <div className="po-settings-nav-group">
          <span className="po-settings-nav-heading">Workspace</span>
          {workspaceSections.map(item => <button type="button" className={section===item?"is-active":""} key={item} aria-current={section===item?"page":undefined} onClick={()=>chooseSection(item)}>{item}</button>)}
        </div>
        <div className="po-settings-nav-group">
          <span className="po-settings-nav-heading">Personal</span>
          {personalSections.map(item => <button type="button" className={section===item?"is-active":""} key={item} aria-current={section===item?"page":undefined} onClick={()=>chooseSection(item)}>{item}</button>)}
        </div>
      </nav>
      <div className="po-settings-body">
        {section==="General" && <Panel><PanelTitle eyebrow="WORKSPACE DEFAULTS" title="General" description="Set the basic details and defaults for this workspace."/><div className="po-settings-form-grid"><label className="po-field-block">Workspace name<input value={generalName} onChange={e=>setGeneralName(e.target.value)}/></label><label className="po-field-block">Time zone<select value={generalTimezone} onChange={e=>setGeneralTimezone(e.target.value)}>{["Asia/Kolkata","UTC","America/Los_Angeles","America/New_York","Europe/London","Asia/Singapore"].map(v=><option key={v}>{v}</option>)}</select></label><label className="po-field-block">Default lead owner<select value={generalOwner} onChange={e=>setGeneralOwner(e.target.value)}>{["First available teammate","Unassigned queue","Workspace owner","Round robin"].map(v=><option key={v}>{v}</option>)}</select></label></div><div className="po-settings-save-row"><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("General workspace settings updated in this local preview only.")}>Save general settings</button><span>Changes are illustrative and are not written to a workspace.</span></div></Panel>}
        {section==="Team & access" && <TeamScreen />}
        {section==="Plan & billing" && <BillingScreen />}
        {section==="Appearance" && <Panel className="po-appearance-settings"><PanelTitle eyebrow="PERSONAL PREFERENCES" title="Appearance" description="Choose a theme and accent palette for this preview."/>
          <section className="po-appearance-group" aria-labelledby="po-appearance-mode-title"><div className="po-appearance-group-heading"><h3 id="po-appearance-mode-title">Theme mode</h3><p>Switch between light and dark surfaces.</p></div><div className="po-appearance-mode-options" role="group" aria-label="Theme mode">
            <button type="button" className={"po-appearance-mode-option"+(theme==="light"?" is-selected":"")} data-theme="light" aria-pressed={theme==="light"} onClick={()=>onChangeTheme("light")}><span className="po-appearance-mode-preview" aria-hidden="true"><span/><span/><i/></span><span className="po-appearance-option-copy"><strong><SunIcon/>Light</strong><small>Bright surfaces</small></span>{theme==="light"&&<CheckCircleIcon className="po-appearance-selected-icon"/>}</button>
            <button type="button" className={"po-appearance-mode-option"+(theme==="dark"?" is-selected":"")} data-theme="dark" aria-pressed={theme==="dark"} onClick={()=>onChangeTheme("dark")}><span className="po-appearance-mode-preview" aria-hidden="true"><span/><span/><i/></span><span className="po-appearance-option-copy"><strong><MoonIcon/>Dark</strong><small>Reduced luminance</small></span>{theme==="dark"&&<CheckCircleIcon className="po-appearance-selected-icon"/>}</button>
          </div></section>
          <section className="po-appearance-group" aria-labelledby="po-appearance-palette-title"><div className="po-appearance-group-heading"><h3 id="po-appearance-palette-title">Accent palette</h3><p>Preview the palette across navigation, actions, selected items and the brand mark.</p></div><div className="po-appearance-palette-grid" role="group" aria-label="Accent palette">{appearancePalettes.map(item=><button type="button" key={item.value} className={"po-appearance-palette-option"+(palette===item.value?" is-selected":"")} data-palette={item.value} aria-pressed={palette===item.value} onClick={()=>onChangePalette(item.value)}><span className="po-appearance-swatches" aria-hidden="true"><i/><i/><i/><i/></span><span className="po-appearance-option-copy"><strong>{item.label}</strong><small>{item.description}</small></span>{palette===item.value&&<CheckCircleIcon className="po-appearance-selected-icon"/>}</button>)}</div><p className="po-appearance-note">Your selection is reflected in the preview URL, so you can bookmark or share a combination.</p></section>
        </Panel>}
        {section==="Profile" && <Panel><PanelTitle eyebrow="PERSONAL ACCOUNT" title="Profile" description="Manage how your name and account details appear to teammates."/><div className="po-profile-card"><span className="po-avatar">AM</span><div><strong>{profileName || "Your name"}</strong><small>{profileEmail}</small><Tag>{profileRole}</Tag></div></div><div className="po-settings-form-grid"><label className="po-field-block">Display name<input value={profileName} onChange={e=>setProfileName(e.target.value)}/></label><label className="po-field-block">Email address<input type="email" value={profileEmail} onChange={e=>setProfileEmail(e.target.value)}/></label><label className="po-field-block">Workspace role<input value={profileRole} readOnly/></label></div><div className="po-settings-save-row"><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("Profile changes are held in this local preview only.")}>Save profile</button><span>Account updates are not sent to a server.</span></div></Panel>}
        {section==="Notifications" && <Panel><PanelTitle eyebrow="PERSONAL PREFERENCES" title="Notifications" description="Choose which updates are important enough to bring to your attention."/><div className="po-settings-toggle-list">
          {[[failureAlerts,setFailureAlerts,"Automation failures","When a journey fails or needs attention"],[handoffAlerts,setHandoffAlerts,"Human handoffs","When a conversation is handed to a teammate"],[leadAlerts,setLeadAlerts,"New qualified leads","When a lead reaches your qualification goal"],[digest,setDigest,"Weekly summary","A weekly overview of lead and automation activity"]].map(([checked,setChecked,title,description]) => <label className="po-settings-toggle-row" key={title as string}><span><strong>{title as string}</strong><small>{description as string}</small></span><input type="checkbox" checked={checked as boolean} onChange={e=>(setChecked as (v:boolean)=>void)(e.target.checked)}/></label>)}
        </div><div className="po-settings-save-row"><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("Notification preferences updated locally in preview only.")}>Save notification preferences</button><span>No email or push notifications are sent from this preview.</span></div></Panel>}
        {section==="Lead fields" && <Panel><PanelTitle title="Lead fields" description="Use business-friendly labels; keep technical keys secondary." action={<Tag>Sample schema</Tag>}/><div className="po-field-table"><div className="po-field-table-row po-field-table-row--header"><span>Label</span><span>Technical key</span><span>Type</span><span>Used for</span><span/></div>{[["Interest","automation_interest","Text","Lead qualification"],["Use case","automation_use_case","Text","Lead qualification"],["Comment volume","comment_volume","Number","Scoring"],["Preferred contact","preferred_contact","Text","Follow-up"],["Phone number","phone_number","Phone","Contact details"]].map(row=><div className="po-field-table-row" key={row[1]}>{row.map((v,i)=><span key={i} className={i===1?"po-technical-key":""}>{v}</span>)}<button type="button" className="po-text-action" onClick={()=>setNotice("Removal would show the journeys that use "+row[0]+". No field was deleted.")}>Remove</button></div>)}</div><div id="po-add-field" className="po-add-field"><label>Field label<input value={newField} onChange={e=>setNewField(e.target.value)} placeholder="e.g. Budget range"/></label><label>Type<select value={fieldType} onChange={e=>setFieldType(e.target.value)}>{["Text","Number","Email","Phone","Date","Country"].map(v=><option key={v}>{v}</option>)}</select></label><button type="button" className="po-button po-button--secondary" disabled={!newField.trim()} onClick={()=>{setNotice("Field "+newField+" ("+fieldType+") shown as a local preview only.");setNewField("");}}>Add field</button></div></Panel>}
        {section==="AI behavior" && <Panel><PanelTitle title="AI behavior" description="How the assistant responds when context is incomplete or uncertain."/><label className="po-field-block">Instructions<textarea rows={6} value={ai} onChange={e=>setAi(e.target.value)}/></label><p className="po-inline-help">Never invent facts, prices, availability, or guarantees.</p><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("AI behavior updated locally in preview only.")}>Save AI behavior</button></Panel>}
        {section==="Forbidden topics" && <Panel><PanelTitle title="Forbidden topics" description="Topics where the assistant should refuse, defer, or escalate."/><label className="po-field-block">Topic list<textarea rows={5} value={forbidden} onChange={e=>setForbidden(e.target.value)}/></label><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("Forbidden-topic draft updated locally only.")}>Save forbidden topics</button></Panel>}
        {section==="Escalation" && <Panel><PanelTitle title="Escalation rules" description="Situations that require human attention."/><label className="po-field-block">Escalation triggers<textarea rows={5} value={escalation} onChange={e=>setEscalation(e.target.value)}/></label><div className="po-warning-note"><span>!</span><span><strong>Ownership matters</strong><small>A human handoff should assign a teammate or appear in an unassigned work queue.</small></span></div><button type="button" className="po-button po-button--primary" onClick={()=>setNotice("Escalation rules updated locally in preview only.")}>Save escalation rules</button></Panel>}
        {section==="Scoring" && <Panel><PanelTitle title="Custom scoring rules" description="Show the signal, points, and reason behind score changes."/><div className="po-scoring-rule"><label>Rule name<input value={rule} onChange={e=>setRule(e.target.value)}/></label><label>Points<input type="number" value={score} onChange={e=>setScore(e.target.value)}/></label><button type="button" className="po-button po-button--secondary" onClick={()=>setNotice("Rule "+rule+" (+"+score+") exists only in preview state.")}>Add rule</button></div><div className="po-row-actions"><button type="button" onClick={()=>setNotice("Sample scoring rule editor opened locally.")}>Edit rule</button><button type="button" onClick={()=>setNotice("Removal confirmation would list affected journeys and leads.")}>Remove rule</button></div></Panel>}
      </div>
    </div>
    {notice&&<div className="po-inline-notice" role="status">{notice}</div>}
  </section>;
}




function GoogleMark() {
  return <svg width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path fill="var(--po-color-brand-google-blue)" d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.9c1.7-1.57 2.7-3.87 2.7-6.62z"/><path fill="var(--po-color-brand-google-green)" d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.9-2.26c-.8.54-1.84.86-3.06.86-2.35 0-4.34-1.59-5.05-3.72H.94v2.33A9 9 0 0 0 9 18z"/><path fill="var(--po-color-brand-google-yellow)" d="M3.95 10.7A5.4 5.4 0 0 1 3.66 9c0-.59.1-1.17.29-1.7V4.97H.94A9 9 0 0 0 .94 13.03z"/><path fill="var(--po-color-brand-google-red)" d="M9 3.58c1.32 0 2.51.46 3.44 1.35l2.58-2.58C13.46.89 11.43 0 9 0A9 9 0 0 0 .94 4.97L3.95 7.3C4.66 5.17 6.65 3.58 9 3.58z"/></svg>;
}

